{{-- CTA band bawah halaman (markup asli situs lama). Props opsional: $ctaTitle, $ctaEm, $ctaText --}}
<section class="page-cta reveal" style="padding: 6rem 5rem; text-align: center; background: linear-gradient(160deg, #0a1628 0%, #051a0f 100%); border-top: 1px solid rgba(0, 224, 160, 0.1); position: relative; overflow: hidden;">
  <div style="position: absolute; top: 50%; left: 50%; transform: translate(-50%, -50%); width: 700px; height: 500px; background: radial-gradient(ellipse at center, rgba(0, 194, 120, 0.18) 0%, transparent 70%); pointer-events: none;"></div>
  <div style="max-width: 700px; margin: 0 auto; position: relative; z-index: 1;">
    <h2 style="font-family: var(--font-serif); font-size: clamp(1.5rem, 2.5vw, 2.2rem); font-weight: 700; color: #ffffff; line-height: 1.3; margin-bottom: 1.2rem; text-align: center;">{{ $ctaTitle ?? 'Siap memulai' }}<br /><em style="font-style: normal; color: #00e0a0;">{{ $ctaEm ?? 'proyek Anda?' }}</em></h2>
    <p style="font-size: 0.88rem; color: rgba(255, 255, 255, 0.7); line-height: 1.7; max-width: 560px; margin: 0 auto; text-align: center; margin-bottom: 32px;">{{ $ctaText ?? 'Ceritakan kebutuhan Anda, dan tim kami akan menyiapkan solusi yang tepat.' }}</p>
    <a href="{{ url('kontak.html') }}" class="btn-outline-yellow" style="font-family: var(--font-sans); font-size: 0.75rem; font-weight: 700; letter-spacing: 0.08em; text-transform: uppercase; padding: 0.95rem 2rem; background: transparent; color: #f0b800; border: 3px solid #f0b800; border-radius: 50px; text-decoration: none; display: inline-block; transition: all 0.3s ease; cursor: pointer;" onmouseover="this.style.background='#f0b800'; this.style.color='#1e3a8a';" onmouseout="this.style.background='transparent'; this.style.color='#f0b800';">Hubungi Kami Sekarang</a>
  </div>
</section>
